"Una cosa: dut, daukat. Varias: ditut, dauzkat. Lo plural es lo que se tiene, no quien tiene: nik liburuak ditut.":"Une chose : dut, daukat. Plusieurs : ditut, dauzkat. Le pluriel, c'est ce qu'on a, pas qui l'a : nik liburuak ditut.",
