"¿Dónde está el baño?":"Où sont les toilettes ?",
"El baño está ahí.":"Les toilettes sont là.",
"Tener con -k en el sujeto":"Avoir, avec -k sur le sujet",
"Etxeak hiru gela ditu: la casa (etxea + -k) tiene (ditu, plural) tres habitaciones. Con una sola cosa: Pisuak balkoi bat du.":"Etxeak hiru gela ditu : la maison (etxea + -k) a (ditu, pluriel) trois pièces. Avec une seule chose : Pisuak balkoi bat du.",
"No tener: ez du … -rik":"Ne pas avoir : ez du … -rik",
"Ez du balkoirik = no tiene balcón. En negativo la cosa que no se tiene lleva -rik y el verbo va justo detrás de ez.":"Ez du balkoirik = il n'a pas de balcon. À la forme négative, la chose qu'on n'a pas prend -rik et le verbe se met juste derrière ez.",
"Dónde está: egon":"Où c'est : egon",
"Non dago komuna? Komuna hor dago. Para lugares y estados se usa egon (dago), no izan (da).":"Non dago komuna? Komuna hor dago. Pour les lieux et les états on utilise egon (dago), pas izan (da).",
"¿Dónde vives, en un piso?":"Où habites-tu, dans un appartement ?",
"Sí, vivo en un piso pequeño. Tiene dos dormitorios.":"Oui, j'habite dans un petit appartement. Il a deux chambres.",
"¿Y balcón?":"Et un balcon ?",
"No, no tiene balcón, pero el salón es muy luminoso.":"Non, il n'a pas de balcon, mais le salon est très lumineux.",
