"etxea → etxera, lana → lanera, Bilbo → Bilbora. Tras consonante, -era: Madril → Madrilera, Irun → Irunera.":"etxea → etxera, lana → lanera, Bilbo → Bilbora. Après consonne, -era : Madril → Madrilera, Irun → Irunera.",
"De dónde: -tik":"D'où : -tik",
"etxetik, lanetik, Bilbotik. Tras -n o -l es -dik: Irundik, Madrildik. Nondik zatoz? Etxetik nator.":"etxetik, lanetik, Bilbotik. Après -n ou -l, c'est -dik : Irundik, Madrildik. Nondik zatoz? Etxetik nator.",
"Ir y venir sin auxiliar":"Aller et venir sans auxiliaire",
"joan y etorri tienen formas cortas: noa (voy), zoaz (vas), doa (va); nator (vengo), zatoz (vienes), dator (viene). Etxera noa, no «etxera joaten naiz».":"joan et etorri ont des formes courtes : noa (je vais), zoaz (tu vas), doa (il va) ; nator (je viens), zatoz (tu viens), dator (il vient). Etxera noa, pas « etxera joaten naiz ».",
