"¿Cómo es? Nolakoa da?":"Comment c'est ? Nolakoa da?",
"La respuesta es adjetivo + -a + da: Etxea handia da, Auzoa lasaia da. El adjetivo va después del nombre y lleva el artículo.":"La réponse est adjectif + -a + da : Etxea handia da, Auzoa lasaia da. L'adjectif vient après le nom et porte l'article.",
"Pero y y":"Mais et et",
"baina = pero, eta = y: zaharra baina polita, handia eta garestia. Solo el último adjetivo suele llevar el verbo da.":"baina = mais, eta = et : zaharra baina polita, handia eta garestia. Seul le dernier adjectif porte en général le verbe da.",
"Muy y bastante":"Très et assez",
"oso = muy, nahiko = bastante, delante del adjetivo: oso polita, nahiko merkea. En plural: pisuak garestiak dira.":"oso = très, nahiko = assez, devant l'adjectif : oso polita, nahiko merkea. Au pluriel : pisuak garestiak dira.",
