  "Futuro: -ko / -go": "Futur : -ko / -go",
  "ikusi → ikusiko dut, erosi → erosiko dut, hartu → hartuko dut, etorri → etorriko naiz. Si el verbo acaba en -n, -go: joan → joango naiz, egin → egingo dut, jan → jango dut.": "ikusi → ikusiko dut, erosi → erosiko dut, hartu → hartuko dut, etorri → etorriko naiz. Si le verbe finit par -n, -go : joan → joango naiz, egin → egingo dut, jan → jango dut.",
  "naiz o dut, como siempre": "naiz ou dut, comme toujours",
  "Con objeto, dut: film bat ikusiko dut. Sin objeto, naiz: mendira joango naiz, etxean geratuko naiz. Nosotros: joango gara / ikusiko dugu.": "Avec complément, dut : film bat ikusiko dut. Sans, naiz : mendira joango naiz, etxean geratuko naiz. Nous : joango gara / ikusiko dugu.",
  "Cuándo: bihar, asteburuan, datorren astean": "Quand : bihar, asteburuan, datorren astean",
  "bihar (mañana), etzi (pasado mañana), asteburuan (el finde), datorren astean / urtean (la semana / el año que viene), oporretan (en vacaciones).": "bihar (demain), etzi (après-demain), asteburuan (ce week-end), datorren astean / urtean (la semaine / l'année prochaine), oporretan (en vacances).",
  "¿Qué vas a hacer el fin de semana?": "Qu'est-ce que tu vas faire ce week-end ?",
  "El sábado iré al monte. Y el domingo, no sé.": "Samedi j'irai à la montagne. Et dimanche, je ne sais pas.",
  "¿El domingo comes con nosotros?": "Dimanche tu déjeunes avec nous ?",
  "¡Sí, muy bien! ¿A qué hora?": "Oui, très bien ! À quelle heure ?",
  "A las dos. ¡Pago yo!": "À deux heures. C'est moi qui paie !",
  "Solo la una es singular: ordu bata da. Las demás llevan -ak y dira: hirurak dira.": "Seule une heure est au singulier : ordu bata da. Les autres prennent -ak et dira : hirurak dira.",
  "Las horas (menos la una) son plural: -ak + dira. Y media: eta erdi; y cuarto: eta laurden; menos cuarto: laurden gutxi.": "Les heures (sauf une heure) sont au pluriel : -ak + dira. Et demie : eta erdi ; et quart : eta laurden ; moins le quart : laurden gutxi.",
  "laurden gutxi = menos cuarto: bostak laurden gutxi = las cinco menos cuarto (4:45).": "laurden gutxi = moins le quart : bostak laurden gutxi = cinq heures moins le quart (4 h 45).",
  "¿A qué hora? -etan: zortzietan (a las ocho), ordu batean (a la una), hirurak eta erdietan (a las tres y media).": "À quelle heure ? -etan : zortzietan (à huit heures), ordu batean (à une heure), hirurak eta erdietan (à trois heures et demie).",
  "goizeko / arratsaldeko / gaueko + hora: goizeko zortziak (las ocho de la mañana).": "goizeko / arratsaldeko / gaueko + heure : goizeko zortziak (huit heures du matin).",
  "Los días llevan -a: gaur astelehena da. Ayer: atzo igandea zen (zen = era/fue).": "Les jours prennent -a : gaur astelehena da. Hier : atzo igandea zen (zen = était).",
  "«Los lunes», cada lunes: -etan: astelehenetan, ostiraletan.": "« Le lundi », chaque lundi : -etan : astelehenetan, ostiraletan.",
  "Fechas: mes + -aren + día: azaroaren hamazazpia (17 de noviembre). Cuándo: maiatzaren bostean (el 5 de mayo).": "Dates : mois + -aren + jour : azaroaren hamazazpia (17 novembre). Quand : maiatzaren bostean (le 5 mai).",
  "Presente habitual sin objeto: -tzen/-ten + naiz: jaikitzen naiz (me levanto), joaten naiz (voy), oheratzen naiz (me acuesto).": "Présent d'habitude sans complément : -tzen/-ten + naiz : jaikitzen naiz (je me lève), joaten naiz (je vais), oheratzen naiz (je me couche).",
  "Presente habitual con objeto: -tzen/-ten + dut: gosaltzen dut (desayuno), irakurtzen dut (leo), kirola egiten dut (hago deporte).": "Présent d'habitude avec complément : -tzen/-ten + dut : gosaltzen dut (je prends le petit-déjeuner), irakurtzen dut (je lis), kirola egiten dut (je fais du sport).",
  "-ero = cada: egunero (cada día), astero (cada semana), hilero (cada mes), goizero (cada mañana).": "-ero = chaque : egunero (chaque jour), astero (chaque semaine), hilero (chaque mois), goizero (chaque matin).",
  "astean behin / bitan / hirutan = una / dos / tres veces a la semana. Zenbatetan? = ¿cuántas veces?": "astean behin / bitan / hirutan = une / deux / trois fois par semaine. Zenbatetan? = combien de fois ?",
  "Nunca: ez + auxiliar + inoiz: ez dut inoiz telebista ikusten.": "Jamais : ez + auxiliaire + inoiz : ez dut inoiz telebista ikusten.",
  "Futuro: verbo + -ko: ikusiko dut (veré), erosiko dut (compraré), etorriko da (vendrá).": "Futur : verbe + -ko : ikusiko dut (je verrai), erosiko dut (j'achèterai), etorriko da (il/elle viendra).",
  "Tras -n el futuro es -go: joan → joango naiz, egin → egingo dut, jan → jango dut.": "Après -n le futur est en -go : joan → joango naiz, egin → egingo dut, jan → jango dut.",
  "datorren = que viene: datorren astean (la semana que viene), datorren urtean (el año que viene).": "datorren = prochain : datorren astean (la semaine prochaine), datorren urtean (l'année prochaine).",
  "Las horas: qué hora es y a qué hora": "Les heures : quelle heure il est et à quelle heure",
  "Solo la una es singular (ordu bata da); el resto plural con -ak y dira (hirurak dira). Y media: eta erdi; y cuarto: eta laurden; menos cuarto: laurden gutxi; y diez: eta hamar. ¿A qué hora? Zer ordutan? → -etan: zortzietan, ordu batean, hirurak eta erdietan.": "Seule une heure est au singulier (ordu bata da) ; le reste au pluriel avec -ak et dira (hirurak dira). Et demie : eta erdi ; et quart : eta laurden ; moins le quart : laurden gutxi ; et dix : eta hamar. À quelle heure ? Zer ordutan? → -etan : zortzietan, ordu batean, hirurak eta erdietan.",
