  "Lo que pasó: el verbo en su forma básica + el auxiliar en pasado. Sin objeto, izan: joan nintzen (fui), etorri zen (vino), geratu ginen. Con objeto, ukan: ikusi nuen (vi), jan nuen, bazkaldu genuen. Preguntar: Zer egin zenuen? Nora joan zinen? Las tres formas: joaten naiz (voy) · joango naiz (iré) · joan nintzen (fui).": "Ce qui s'est passé : le verbe à sa forme de base + l'auxiliaire au passé. Sans complément, izan : joan nintzen (je suis allé), etorri zen (il est venu), geratu ginen. Avec complément, ukan : ikusi nuen (j'ai vu), jan nuen, bazkaldu genuen. Demander : Zer egin zenuen? Nora joan zinen? Les trois formes : joaten naiz (je vais) · joango naiz (j'irai) · joan nintzen (je suis allé).",
