  "Terminé la universidad y empecé a trabajar.": "J'ai fini l'université et j'ai commencé à travailler.",
  "Antes no cocinaba; ahora cocino cada día.": "Avant, je ne cuisinais pas ; maintenant je cuisine tous les jours.",
  "He empezado a hacer deporte.": "J'ai commencé à faire du sport.",
  "¿Tú sabes bailar?": "Tu sais danser ?",
  "He cambiado muchas costumbres.": "J'ai changé beaucoup d'habitudes.",
  "Antes me acostaba tarde; ahora me acuesto temprano.": "Avant, je me couchais tard ; maintenant je me couche tôt.",
  "Empezar a: -tzen hasi": "Commencer à : -tzen hasi",
  "hasi (empezar) y bukatu (terminar) van con el verbo en -tzen: euskara ikasten hasi nintzen, lanean hasi naiz. hasi es como joan: hasi naiz, hasi nintzen (sin objeto).": "hasi (commencer) et bukatu (finir) prennent le verbe en -tzen : euskara ikasten hasi nintzen, lanean hasi naiz. hasi fonctionne comme joan : hasi naiz, hasi nintzen (sans objet).",
  "Saber hacer: -tzen jakin": "Savoir faire : -tzen jakin",
  "badakit igeri egiten (sé nadar), ez dakit gidatzen (no sé conducir), badakizu dantzatzen? El pasado de dakit es nekien: lehen ez nekien.": "badakit igeri egiten (je sais nager), ez dakit gidatzen (je ne sais pas conduire), badakizu dantzatzen ? Le passé de dakit est nekien : lehen ez nekien.",
  "Hace dos años: duela bi urte": "Il y a deux ans : duela bi urte",
  "duela + tiempo = hace: duela bi urte (hace dos años), duela hilabete bat (hace un mes), duela aste bat (hace una semana).": "duela + durée = il y a : duela bi urte (il y a deux ans), duela hilabete bat (il y a un mois), duela aste bat (il y a une semaine).",
  "Hace dos años. Antes no sabía nada; ahora sé un poco.": "Il y a deux ans. Avant, je ne savais rien ; maintenant j'en sais un peu.",
  "¡Muy bien! ¿Y qué más has aprendido?": "Très bien ! Et qu'as-tu appris d'autre ?",
  "¡A cocinar! Antes no cocinaba nunca.": "À cuisiner ! Avant, je ne cuisinais jamais.",
  "¿Y sabes bailar?": "Et tu sais danser ?",
  "No, eso no sé… ¡todavía!": "Non, ça je ne sais pas… pas encore !",
  "Había: zegoen (una cosa), zeuden (varias). Lantegi bat zegoen, denda asko zeuden. Es el pasado de dago / daude.": "Il y avait : zegoen (une chose), zeuden (plusieurs). Lantegi bat zegoen, denda asko zeuden. C'est le passé de dago / daude.",
  "No había: ez zegoen + cosa con -rik: ez zegoen supermerkaturik, ez zegoen elektrizitaterik.": "Il n'y avait pas : ez zegoen + chose avec -rik : ez zegoen supermerkaturik, ez zegoen elektrizitaterik.",
  "garai hartan = en aquella época. Va con el pasado: garai hartan lantegi bat zegoen.": "garai hartan = à cette époque. Va avec le passé : garai hartan lantegi bat zegoen.",
  "aspaldi = hace mucho tiempo. Aspaldi iritsi zen (llegó hace mucho). Aspaldiko! = ¡cuánto tiempo!": "aspaldi = il y a longtemps. Aspaldi iritsi zen (il est arrivé il y a longtemps). Aspaldiko ! = ça fait longtemps !",
  "Más: -ago. txikiagoa (más pequeño), lasaiagoa (más tranquilo). En plural -agoak: kaleak lasaiagoak ziren.": "Plus : -ago. txikiagoa (plus petit), lasaiagoa (plus tranquille). Au pluriel -agoak : kaleak lasaiagoak ziren.",
  "Pasado habitual sin objeto: -tzen + nintzen: jolasten nintzen (jugaba), joaten ginen (íbamos), jaikitzen ziren (se levantaban).": "Passé d'habitude sans objet : -tzen + nintzen : jolasten nintzen (je jouais), joaten ginen (nous allions), jaikitzen ziren (ils se levaient).",
  "Pasado habitual con objeto: -tzen + nuen: ikusten nuen (veía), jaten genuen (comíamos), egiten zuen (hacía).": "Passé d'habitude avec objet : -tzen + nuen : ikusten nuen (je regardais), jaten genuen (nous mangions), egiten zuen (il/elle faisait).",
  "Pasado habitual con varias cosas: -tzen + nituen: marrazki bizidunak ikusten nituen, ipuinak kontatzen zituen.": "Passé d'habitude avec plusieurs choses : -tzen + nituen : marrazki bizidunak ikusten nituen, ipuinak kontatzen zituen.",
  "Nunca: ez + auxiliar + inoiz + verbo: ez nuen inoiz barazkirik jaten (nunca comía verdura). La cosa negada lleva -rik.": "Jamais : ez + auxiliaire + inoiz + verbe : ez nuen inoiz barazkirik jaten (je ne mangeais jamais de légumes). La chose niée prend -rik.",
  "zitzaidan = me gustaba (una cosa). Pasado de zait: musika gustatzen zitzaidan. Para «te gustaba», zitzaizun; «le gustaba», zitzaion.": "zitzaidan = j'aimais (une chose). Passé de zait : musika gustatzen zitzaidan. « Tu aimais » : zitzaizun ; « il/elle aimait » : zitzaion.",
  "zitzaizkidan = me gustaban (varias). Pasado de zaizkit, con -zki-: azterketak ez zitzaizkidan gustatzen.": "zitzaizkidan = j'aimais (plusieurs). Passé de zaizkit, avec -zki- : azterketak ez zitzaizkidan gustatzen.",
  "zitzaizun = te gustaba. Zein ikasgai gustatzen zitzaizun? (¿qué asignatura te gustaba?)": "zitzaizun = tu aimais. Zein ikasgai gustatzen zitzaizun ? (quelle matière aimais-tu ?)",
  "gehien = lo que más. Va al final: jolastordua gustatzen zitzaidan gehien. Lo que menos: gutxien.": "gehien = le plus. Va à la fin : jolastordua gustatzen zitzaidan gehien. Le moins : gutxien.",
  "Estaba haciendo: ari + pasado de izan: lanean ari zen (estaba trabajando), ari ziren (estaban). Presente: ari naiz.": "Était en train de : ari + passé de izan : lanean ari zen (était en train de travailler), ari ziren (étaient). Présent : ari naiz.",
  "Empezar / terminar a hacer algo: verbo en -tzen + hasi / bukatu: euskara ikasten hasi nintzen, lanean hasi naiz.": "Commencer / finir de faire quelque chose : verbe en -tzen + hasi / bukatu : euskara ikasten hasi nintzen, lanean hasi naiz.",
  "Saber hacer: -tzen + jakin: badakit igeri egiten (sé nadar), ez dakit gidatzen. Pasado: ez nekien (no sabía).": "Savoir faire : -tzen + jakin : badakit igeri egiten (je sais nager), ez dakit gidatzen. Passé : ez nekien (je ne savais pas).",
  "nekien = sabía (pasado de dakit). Lehen ez nekien euskaraz (antes no sabía euskera). Tú: zenekien; él/ella: zekien.": "nekien = je savais (passé de dakit). Lehen ez nekien euskaraz (avant je ne savais pas le basque). Toi : zenekien ; il/elle : zekien.",
  "duela + tiempo = hace: duela bi urte (hace dos años), duela aste bat (hace una semana). Va con el pasado: duela bi urte hasi nintzen.": "duela + durée = il y a : duela bi urte (il y a deux ans), duela aste bat (il y a une semaine). Va avec le passé : duela bi urte hasi nintzen.",
  "El verbo como nombre lleva -t(z)ea: irakurtzea gustatzen zait (me gusta leer), mendira joatea nahi dut.": "Le verbe employé comme nom prend -t(z)ea : irakurtzea gustatzen zait (j'aime lire), mendira joatea nahi dut.",
  "Pasado habitual: lo que hacía": "Passé d'habitude : ce que je faisais",
  "Lo que hacías habitualmente en el pasado: verbo en -tzen / -ten + auxiliar en pasado. Sin objeto, izan: jolasten nintzen (jugaba), joaten ginen (íbamos). Con objeto, ukan: ikusten nuen (veía), egiten zuen (hacía); con varias cosas, nituen / zituen. Es el mismo esquema que el presente habitual (jolasten naiz, ikusten dut) con el auxiliar cambiado.": "Ce que tu faisais habituellement dans le passé : verbe en -tzen / -ten + auxiliaire au passé. Sans objet, izan : jolasten nintzen (je jouais), joaten ginen (nous allions). Avec objet, ukan : ikusten nuen (je regardais), egiten zuen (il/elle faisait) ; avec plusieurs choses, nituen / zituen. Même schéma que le présent d'habitude (jolasten naiz, ikusten dut) avec l'auxiliaire changé.",
  "presente habitual": "présent d'habitude",
  "pasado habitual": "passé d'habitude",
