  "Había: zegoen, zeuden, ez zegoen …-rik": "Il y avait : zegoen, zeuden, ez zegoen …-rik",
  "Para «había» se usa el pasado de egon: zegoen (una cosa), zeuden (varias). Preguntar: bazegoen …-rik? Afirmar con énfasis: bai, bazegoen. Negar: ez zegoen …-rik. Igual que en presente (dago / daude / ez dago …-rik) pero en pasado. Con garai hartan, lehen, aspaldi.": "Pour « il y avait » on utilise le passé de egon : zegoen (une chose), zeuden (plusieurs). Demander : bazegoen …-rik ? Affirmer avec insistance : bai, bazegoen. Nier : ez zegoen …-rik. Comme au présent (dago / daude / ez dago …-rik) mais au passé. Avec garai hartan, lehen, aspaldi.",
  "presente": "présent",
  "hay / había (una)": "il y a / avait (une)",
