  "te los devolveré": "je te les rendrai",
  "toma": "tiens",
  "el lunes": "lundi",
  "olvidar": "oublier",
  "perder": "perdre",
  "¿Me dejas el bolígrafo?": "Tu me prêtes le stylo ?",
  "Sí, toma.": "Oui, tiens.",
  "¿Me dejas el cargador, por favor?": "Tu me prêtes le chargeur, s'il te plaît ?",
  "Te lo devolveré mañana.": "Je te le rendrai demain.",
  "¿Me dejas un poco de dinero?": "Tu me prêtes un peu d'argent ?",
  "Te lo devuelvo el lunes, tranquilo/a.": "Je te le rends lundi, ne t'inquiète pas.",
  "Le he dejado las llaves a Miren.": "J'ai laissé les clés à Miren.",
  "Todavía no me las ha devuelto.": "Il/elle ne me les a pas encore rendues.",
  "Le dejé el paraguas y lo ha perdido.": "Je lui ai prêté le parapluie et il/elle l'a perdu.",
  "Le he pedido el libro al profesor.": "J'ai demandé le livre au professeur.",
  "¿Te he devuelto tus llaves?": "Je t'ai rendu tes clés ?",
  "¡Se me ha olvidado!": "J'ai oublié !",
  "¿Me dejas…?: utziko didazu?": "Tu me prêtes… ? : utziko didazu ?",
  "didazu = tú a mí: utziko didazu? (¿me dejas?), emango didazu? (¿me das?). Y al revés, yo a ti: dizut: itzuliko dizut (te lo devolveré).": "didazu = toi à moi : utziko didazu ? (tu me prêtes ?), emango didazu ? (tu me donnes ?). Et dans l'autre sens, moi à toi : dizut : itzuliko dizut (je te le rendrai).",
  "Devolver algo a alguien: itzuli": "Rendre quelque chose à quelqu'un : itzuli",
  "itzuli con nor-nori-nork: itzuliko dizut (te lo devolveré), itzuli dit (me lo ha devuelto), ez dizkit itzuli (no me los ha devuelto).": "itzuli avec nor-nori-nork : itzuliko dizut (je te le rendrai), itzuli dit (il/elle me l'a rendu), ez dizkit itzuli (il/elle ne me les a pas rendus).",
  "Dejar y pedir": "Prêter et demander",
  "utzi (dejar, prestar): giltzak utzi dizkiot. eskatu (pedir): liburua eskatu diot. El que recibe siempre con -ri: Mireni, irakasleari.": "utzi (laisser, prêter) : giltzak utzi dizkiot. eskatu (demander) : liburua eskatu diot. Celui qui reçoit prend toujours -ri : Mireni, irakasleari.",
  "¿Me dejas el cargador, por favor? Tengo el móvil muerto.": "Tu me prêtes le chargeur, s'il te plaît ? Mon portable est à plat.",
  "Sí, toma. ¡Pero devuélvelo, eh! Ayer Jon me pidió el paraguas y todavía no me lo ha devuelto.": "Oui, tiens. Mais rends-le, hein ! Hier Jon m'a demandé le parapluie et il ne me l'a toujours pas rendu.",
  "Tranquila, te lo devuelvo en media hora.": "T'inquiète, je te le rends dans une demi-heure.",
  "Decir y preguntar": "Dire et demander",
  "Esan dit, galdetu diot · azaldu, erakutsi": "Esan dit, galdetu diot · azaldu, erakutsi",
  "Euskaltegian · en el euskaltegi": "Euskaltegian · à l'euskaltegi (école de basque)",
  "Zer esan dizu? · ___ esan dit": "Zer esan dizu? · ___ esan dit",
  "decir": "dire",
  "explicar": "expliquer",
  "enseñar, mostrar": "montrer",
  "recomendar": "recommander",
  "me ha dicho": "il/elle m'a dit",
  "le he dicho": "je lui ai dit",
  "te he preguntado": "je t'ai demandé",
  "le he respondido (varias)": "je lui ai répondu (plusieurs)",
  "la verdad": "la vérité",
  "la mentira": "le mensonge",
  "el secreto": "le secret",
  "la pregunta": "la question",
  "la respuesta": "la réponse",
  "la noticia": "la nouvelle",
  "un chiste": "une blague",
  "¿Quién te lo ha dicho?": "Qui te l'a dit ?",
  "¿Qué te ha dicho Miren?": "Qu'est-ce que Miren t'a dit ?",
  "Me ha dicho la verdad.": "Il/elle m'a dit la vérité.",
  "Le he hecho una pregunta al profesor.": "J'ai posé une question au professeur.",
  "¿Y qué te ha respondido?": "Et qu'est-ce qu'il/elle t'a répondu ?",
  "Me lo ha explicado bien.": "Il/elle me l'a bien expliqué.",
  "¿Me lo explicas otra vez, por favor?": "Tu me l'expliques encore une fois, s'il te plaît ?",
  "Te voy a contar un secreto.": "Je vais te raconter un secret.",
  "¡No se lo digas a nadie!": "Ne le dis à personne !",
  "Nos ha enseñado las fotos.": "Il/elle nous a montré les photos.",
  "Me han recomendado este libro.": "On m'a recommandé ce livre.",
  "Nos ha contado un chiste y nos hemos reído mucho.": "Il/elle nous a raconté une blague et on a beaucoup ri.",
  "¿Quién te ha dicho eso? ¡Es mentira!": "Qui t'a dit ça ? C'est faux !",
  "Decir a alguien: esan dit, esan diot": "Dire à quelqu'un : esan dit, esan diot",
  "esan, galdetu, erantzun, kontatu, azaldu, erakutsi llevan nor-nori-nork: esan dit (me ha dicho), galdetu diot (le he preguntado), erakutsi dizkigu (nos ha enseñado varias cosas).": "esan, galdetu, erantzun, kontatu, azaldu, erakutsi prennent le nor-nori-nork : esan dit (il/elle m'a dit), galdetu diot (je lui ai demandé), erakutsi dizkigu (il/elle nous a montré plusieurs choses).",
  "Quién a quién": "Qui à qui",
  "Mirenek esan dit: Miren (con -k, hace) a mí (dit). Nik Mireni esan diot: yo (nik) a Miren (-i, diot). El -k marca quién lo hace; el -ri, quién lo recibe.": "Mirenek esan dit : Miren (avec -k, celle qui agit) à moi (dit). Nik Mireni esan diot : moi (nik) à Miren (-i, diot). Le -k marque qui agit ; le -ri, qui reçoit.",
  "A nadie: inori": "À personne : inori",
  "inor (nadie) con dativo: inori. Ez esan inori! (¡no se lo digas a nadie!). Y «a alguien»: norbaiti.": "inor (personne) au datif : inori. Ez esan inori ! (ne le dis à personne !). Et « à quelqu'un » : norbaiti.",
  "¿Qué te ha dicho el profesor?": "Qu'est-ce que le professeur t'a dit ?",
  "Que he hecho bien el examen. Y le he hecho una pregunta sobre el nor-nori-nork.": "Que j'ai bien réussi l'examen. Et je lui ai posé une question sur le nor-nori-nork.",
  "¿Y te lo ha explicado bien?": "Et il te l'a bien expliqué ?",
  "Muy bien. Luego te lo explico yo.": "Très bien. Je te l'expliquerai tout à l'heure.",
  "Mensajes y llamadas": "Messages et appels",
  "Bidali diot, deitu dizut · eskerrak eman": "Bidali diot, deitu dizut · eskerrak eman",
  "Familiarekin harremanetan · en contacto con la familia": "Familiarekin harremanetan · en contact avec la famille",
  "___-ri mezu bat bidali diot": "___-ri mezu bat bidali diot",
