  "Pregunta: ¿me dejas?": "Demande : tu me prêtes ?",
  "Varias cosas a alguien: dizki-": "Plusieurs choses à quelqu'un : dizki-",
  "Si lo que se da, dice o envía es plural, el auxiliar añade -zki-: dit → dizkit, dizut → dizkizut, diot → dizkiot, digu → dizkigu, didazu → dizkidazu, dizuet → dizkizuet. Es la misma idea que dut → ditut. Eskerrak (gracias) y giltzak (llaves) son plural: eskerrak eman dizkiot, giltzak utzi dizkizut.": "Si ce qu'on donne, dit ou envoie est au pluriel, l'auxiliaire ajoute -zki- : dit → dizkit, dizut → dizkizut, diot → dizkiot, digu → dizkigu, didazu → dizkidazu, dizuet → dizkizuet. Même idée que dut → ditut. Eskerrak (merci) et giltzak (clés) sont au pluriel : eskerrak eman dizkiot, giltzak utzi dizkizut.",
  "varias cosas": "plusieurs choses",
  "Le he dado las gracias.": "Je l'ai remercié(e).",
  "Ahora son unas flores (plural)": "Maintenant ce sont des fleurs (pluriel)",
  "Ahora son las fotos (plural)": "Maintenant ce sont les photos (pluriel)",
  "Ahora son las llaves (plural)": "Maintenant ce sont les clés (pluriel)",
  "Ahora es un libro (singular)": "Maintenant c'est un livre (singulier)",
  "Corrígelo: las llaves son varias": "Corrige : les clés sont plusieurs",
  "A quién: el dativo -ri": "À qui : le datif -ri",
  "El que recibe algo lleva el dativo: -ri tras vocal (Aneri, amari, lagunari), -i tras consonante (Mireni, Joni, irakasleari ← irakaslea), -ei en plural (lagunei, gurasoei). Pronombres: niri, zuri, hari, guri, zuei, haiei. Nori? = ¿a quién? Con nombres comunes se añade el artículo: ama → amari, laguna → lagunari, irakaslea → irakasleari.": "Celui qui reçoit prend le datif : -ri après voyelle (Aneri, amari, lagunari), -i après consonne (Mireni, Joni, irakasleari ← irakaslea), -ei au pluriel (lagunei, gurasoei). Pronoms : niri, zuri, hari, guri, zuei, haiei. Nori ? = à qui ? Avec les noms communs on ajoute l'article : ama → amari, laguna → lagunari, irakaslea → irakasleari.",
  "a quién (nori)": "à qui (nori)",
  "lagunak (pl.)": "lagunak (pl.)",
