  "¿A quién le has dado el libro? A Ane.": "À qui as-tu donné le livre ? À Ane.",
  "Le he preguntado al profesor.": "J'ai demandé au professeur.",
  "Les he enviado un mensaje a mis padres.": "J'ai envoyé un message à mes parents.",
