  "Me dijo, le dije: nor-nori-nork en pasado": "Il/elle m'a dit, je lui ai dit : nor-nori-nork au passé",
  "En pasado, las formas más usadas: zidan (él/ella a mí), zizun (a ti), zion (a él/ella), zigun (a nosotros); nion (yo a él/ella), nizun (yo a ti); genion (nosotros a él/ella); zidaten (ellos a mí), zioten (ellos a él/ella); zenidan (tú a mí). Con varias cosas, -zki-: zizkidan, nizkion, genizkion. Como todo el pasado, empiezan por z- (n- si lo hago yo, g- nosotros, zen- tú) y acaban en -n.": "Au passé, les formes les plus utilisées : zidan (il/elle à moi), zizun (à toi), zion (à lui/elle), zigun (à nous) ; nion (moi à lui/elle), nizun (moi à toi) ; genion (nous à lui/elle) ; zidaten (eux à moi), zioten (eux à lui/elle) ; zenidan (toi à moi). Avec plusieurs choses, -zki- : zizkidan, nizkion, genizkion. Comme tout le passé, elles commencent par z- (n- si c'est moi, g- nous, zen- toi) et finissent en -n.",
  "quién → a quién": "qui → à qui",
