  "¡No bebas demasiado, tienes que conducir!": "Ne bois pas trop, tu dois conduire !",
  "Coge la copa por el pie, no por arriba.": "Tiens le verre par le pied, pas par le haut.",
  "Prefiero el blanco, seco.": "Je préfère le blanc, sec.",
  "¡Llévate una botella a casa!": "Emporte une bouteille à la maison !",
  "Los sentidos en imperativo": "Les sens à l'impératif",
  "begiratu (mira), usaindu (huele), dastatu / probatu (prueba), entzun (escucha), ukitu (toca). Todas en forma básica cuando son órdenes.": "begiratu (regarde), usaindu (sens), dastatu / probatu (goûte), entzun (écoute), ukitu (touche). Toutes à la forme de base quand ce sont des ordres.",
  "Demasiado: gehiegi": "Trop : gehiegi",
  "gehiegi (demasiado) va detrás: ardo gehiegi (demasiado vino), ez edan gehiegi (no bebas demasiado). Lo contrario, gutxiegi (demasiado poco).": "gehiegi (trop) se place après : ardo gehiegi (trop de vin), ez edan gehiegi (ne bois pas trop). Le contraire, gutxiegi (trop peu).",
  "Hecho con: -ekin egina": "Fait avec : -ekin egina",
  "hemengo mahatsarekin egina dago (está hecho con uva de aquí). egina (hecho) con egon: egina dago, eginak daude.": "hemengo mahatsarekin egina dago (il est fait avec du raisin d'ici). egina (fait) avec egon : egina dago, eginak daude.",
  "¡Bienvenidos! Coged una copa y mirad el color.": "Bienvenue ! Prenez un verre et regardez la couleur.",
  "Es muy oscuro.": "Il est très foncé.",
  "Sí, es un tinto joven. Ahora oledlo y catadlo despacio.": "Oui, c'est un rouge jeune. Maintenant sentez-le et goûtez-le lentement.",
  "Mmm, ¡muy bueno! Me llevaré una botella.": "Mmm, très bon ! Je vais prendre une bouteille.",
  "Pero cuidado: ¡no bebas demasiado, tienes que conducir!": "Mais attention : ne bois pas trop, tu dois conduire !",
  "¿Cómo se llega?": "Comment y aller ?",
  "Biasteriko kale estuetan · en las calles estrechas de Laguardia": "Biasteriko kale estuetan · dans les rues étroites de Laguardia",
  "Jarraitu zuzen, ___ kalean hartu ezkerrera": "Jarraitu zuzen, ___ kalean hartu ezkerrera",
