  "me he perdido": "je me suis perdu(e)",
  "está cerca": "c'est près",
  "cinco minutos a pie": "cinq minutes à pied",
  "Perdona, ¿cómo se llega a la plaza?": "Pardon, comment on va à la place ?",
  "Sigue recto por esta calle.": "Continue tout droit par cette rue.",
  "En la segunda calle gira a la izquierda.": "À la deuxième rue, tourne à gauche.",
  "Cruza la calle en el semáforo.": "Traverse la rue au feu.",
  "Sube la calle hasta la iglesia.": "Monte la rue jusqu'à l'église.",
  "La plaza está enfrente de la iglesia.": "La place est en face de l'église.",
  "Pasa la puerta de la muralla y baja las escaleras.": "Passe la porte des remparts et descends les escaliers.",
  "En la rotonda gira a la derecha.": "Au rond-point, tourne à droite.",
  "Me he perdido. ¿Dónde está la bodega?": "Je me suis perdu(e). Où est la cave ?",
  "Está cerca, cinco minutos a pie.": "C'est près, cinq minutes à pied.",
  "No cojas la primera calle, sino la segunda.": "Ne prends pas la première rue, mais la deuxième.",
  "¡Muchas gracias! De nada.": "Merci beaucoup ! De rien.",
  "Indicar el camino": "Indiquer le chemin",
  "Órdenes en forma básica: jarraitu zuzen (sigue recto), hartu ezkerrera / eskuinera (gira), gurutzatu (cruza), igo / jaitsi (sube / baja), pasatu (pasa).": "Ordres à la forme de base : jarraitu zuzen (continue tout droit), hartu ezkerrera / eskuinera (tourne), gurutzatu (traverse), igo / jaitsi (monte / descends), pasatu (passe).",
  "Hasta: -raino": "Jusqu'à : -raino",
  "elizaraino (hasta la iglesia), plazaraino, zubiraino. Es -ra (a) + -ino: igo kalea elizaraino.": "elizaraino (jusqu'à l'église), plazaraino, zubiraino. C'est -ra (à) + -ino : igo kalea elizaraino.",
  "Sino: baizik": "Mais (plutôt) : baizik",
  "Para corregir: ez X, Y baizik (no X, sino Y). Ez hartu lehenengo kalea, bigarrena baizik. baizik va al final.": "Pour corriger : ez X, Y baizik (pas X, mais Y). Ez hartu lehenengo kalea, bigarrena baizik. baizik va à la fin.",
  "Perdona, me he perdido. ¿Cómo se llega a la plaza?": "Pardon, je me suis perdu(e). Comment on va à la place ?",
  "Es fácil. Sigue recto, y en la segunda calle gira a la izquierda.": "C'est facile. Continue tout droit, et à la deuxième rue tourne à gauche.",
  "¿En la segunda, no en la primera?": "À la deuxième, pas à la première ?",
  "Sí, en la segunda. Luego sube la calle hasta la iglesia. La plaza está enfrente.": "Oui, à la deuxième. Ensuite monte la rue jusqu'à l'église. La place est en face.",
  "¿Está lejos?": "C'est loin ?",
  "No, cinco minutos a pie.": "Non, cinq minutes à pied.",
  "Hobe duzu ___ · ___ behar duzu · ez kezkatu": "Hobe duzu ___ · ___ behar duzu · ez kezkatu",
  "Lagun bati laguntzen · ayudando a un amigo": "Lagun bati laguntzen · en aidant un ami",
