  "el tiempo": "le temps",
  "poco a poco": "petit à petit",
  "menos": "moins",
  "en mi opinión": "à mon avis",
  "Estoy muy estresado/a con el trabajo.": "Je suis très stressé(e) par le travail.",
  "En mi opinión, es mejor que descanses.": "À mon avis, tu ferais mieux de te reposer.",
  "Tienes que dormir más.": "Tu dois dormir plus.",
  "No tienes que trabajar tanto.": "Tu n'as pas besoin de travailler autant.",
  "No te preocupes, todo saldrá bien.": "Ne t'inquiète pas, tout ira bien.",
  "Es mejor que hables euskera con los amigos.": "Tu ferais mieux de parler basque avec tes amis.",
  "Tienes que estudiar un poco cada día, poco a poco.": "Tu dois étudier un peu chaque jour, petit à petit.",
  "Intenta tranquilizarte, no tienes prisa.": "Essaie de te calmer, tu n'es pas pressé(e).",
  "Es mejor que vayas al médico.": "Tu ferais mieux d'aller chez le médecin.",
  "Tómate tiempo para ti.": "Prends du temps pour toi.",
  "¡No bebas tanto café!": "Ne bois pas autant de café !",
  "Gracias por el consejo.": "Merci pour le conseil.",
  "Es mejor que: hobe duzu + verbo": "Tu ferais mieux de : hobe duzu + verbe",
  "hobe duzu + verbo en forma básica: hobe duzu atseden hartu (mejor que descanses), hobe duzu joan (mejor que vayas). Para él/ella: hobe du; para mí: hobe dut.": "hobe duzu + verbe à la forme de base : hobe duzu atseden hartu (tu ferais mieux de te reposer), hobe duzu joan (tu ferais mieux d'y aller). Pour lui/elle : hobe du ; pour moi : hobe dut.",
  "Tienes que: behar duzu": "Tu dois : behar duzu",
  "verbo + behar duzu: lo egin behar duzu. Negativo: ez duzu … behar: ez duzu hainbeste lan egin behar (no tienes que trabajar tanto).": "verbe + behar duzu : lo egin behar duzu. Négatif : ez duzu … behar : ez duzu hainbeste lan egin behar (tu n'as pas besoin de travailler autant).",
  "No te preocupes: ez kezkatu": "Ne t'inquiète pas : ez kezkatu",
  "Órdenes negativas útiles: ez kezkatu (no te preocupes), ez ahaztu (no olvides), ez joan (no vayas), ez esan (no digas). Y una positiva: saiatu (intenta).": "Ordres négatifs utiles : ez kezkatu (ne t'inquiète pas), ez ahaztu (n'oublie pas), ez joan (n'y va pas), ez esan (ne dis pas). Et un positif : saiatu (essaie).",
  "Estoy muy estresada. No duermo bien.": "Je suis très stressée. Je ne dors pas bien.",
  "En mi opinión, es mejor que descanses. ¡Y no bebas tanto café!": "À mon avis, tu ferais mieux de te reposer. Et ne bois pas autant de café !",
  "No te preocupes. Tómate tiempo para ti, poco a poco. Todo saldrá bien.": "Ne t'inquiète pas. Prends du temps pour toi, petit à petit. Tout ira bien.",
  "Carteles y avisos": "Panneaux et avis",
  "Kalean eta eraikinetan · en la calle y en los edificios": "Kalean eta eraikinetan · dans la rue et dans les bâtiments",
  "Ez ___ · ___ debekatuta dago": "Ez ___ · ___ debekatuta dago",
