  "El superlativo es -ena pegado al adjetivo: handiena (el más grande), politena, onena (el mejor), txarrena (el peor), gogokoena (el favorito). Cuando va con un nombre, el nombre lleva -rik: hiririk handiena (la ciudad más grande), lekurik politena. El grupo de referencia lleva -ko: Euskal Herriko hiririk handiena, munduko onena, taldeko gazteena; o denetan (de todos).": "Le superlatif, c'est -ena collé à l'adjectif : handiena (le plus grand), politena, onena (le meilleur), txarrena (le pire), gogokoena (le préféré). Avec un nom, le nom prend -rik : hiririk handiena (la plus grande ville), lekurik politena. Le groupe de référence prend -ko : Euskal Herriko hiririk handiena, munduko onena, taldeko gazteena ; ou denetan (de tous).",
  "superlativo": "superlatif",
  "con nombre": "avec un nom",
  "El queso de Idiazabal es el mejor del mundo.": "Le fromage d'Idiazabal est le meilleur du monde.",
  "Ponlo en superlativo": "Mets-le au superlatif",
