  "Dilo con «la más joven del grupo»": "Dis-le avec « la plus jeune du groupe »",
  "Tan … como: bezain, bezala": "Aussi … que : bezain, bezala",
  "Igualdad: X bezain + adjetivo (tan … como): Miren bezain altua (tan alta como Miren). Negativo: ez da … bezain …: Lizarra ez da Iruñea bezain handia. Con verbos, bezala (como): zuk bezala (como tú), lehen bezala (como antes). Igual: berdina; diferente: ezberdina. Y para describir «el de…»: -ko / -dun: sudur handikoa, betaurrekoduna.": "Égalité : X bezain + adjectif (aussi … que) : Miren bezain altua (aussi grande que Miren). Négatif : ez da … bezain … : Lizarra ez da Iruñea bezain handia. Avec des verbes, bezala (comme) : zuk bezala (comme toi), lehen bezala (comme avant). Pareil : berdina ; différent : ezberdina. Et pour décrire « celui à… » : -ko / -dun : sudur handikoa, betaurrekoduna.",
  "X bezain + adj.": "X bezain + adj.",
  "tan alta como Miren": "aussi grande que Miren",
