  "Verbo + -tako (o -dako si el verbo acaba en -n) convierte una acción pasada en adjetivo, delante del nombre: erositako liburua (el libro comprado), ikusitako filma (la película vista), egindako tarta (la tarta hecha), esandakoa (lo dicho). Quien lo hizo va delante con -k: amak egindako tarta (la tarta que hizo mamá), Anek gomendatutako liburua. Es la forma más sencilla de decir «el X que hice / que hizo alguien».": "Verbe + -tako (ou -dako si le verbe finit en -n) transforme une action passée en adjectif, devant le nom : erositako liburua (le livre acheté), ikusitako filma (le film vu), egindako tarta (le gâteau fait), esandakoa (ce qui a été dit). Celui qui l'a fait se place devant avec -k : amak egindako tarta (le gâteau que maman a fait), Anek gomendatutako liburua. C'est la façon la plus simple de dire « le X que j'ai / que quelqu'un a fait ».",
