  "Servicios y gestiones": "Services et démarches",
  "Banco y correos, pedir cita, por teléfono, problemas en casa, la estación: dezaket, naiteke, -rako, -rentzat": "Banque et poste, prendre rendez-vous, au téléphone, problèmes à la maison, la gare : dezaket, naiteke, -rako, -rentzat",
