  "el turno": "le ticket d'attente",
  "¿Puedo sacar dinero en este cajero?": "Je peux retirer de l'argent à ce distributeur ?",
  "Sí, pero necesitas la tarjeta.": "Oui, mais il te faut la carte.",
  "Se me ha olvidado la contraseña.": "J'ai oublié le mot de passe.",
  "Quiero abrir una cuenta.": "Je veux ouvrir un compte.",
  "Tienes que rellenar y firmar este formulario.": "Tu dois remplir et signer ce formulaire.",
  "¿Has traído el DNI?": "Tu as apporté ta carte d'identité ?",
  "Puedes hacer una transferencia desde el móvil.": "Tu peux faire un virement depuis ton portable.",
  "Quiero enviar este paquete a Francia.": "Je veux envoyer ce colis en France.",
  "¿Cuánto cuesta el sello?": "Combien coûte le timbre ?",
  "Recibirás el paquete mañana.": "Tu recevras le colis demain.",
  "Coge turno y espere, por favor.": "Prenez un ticket et attendez, s'il vous plaît.",
  "No puedo venir hoy; ¿puedo venir mañana?": "Je ne peux pas venir aujourd'hui ; je peux venir demain ?",
  "Puedo: dezaket": "Je peux : dezaket",
  "Para «poder» con un objeto (sacar dinero, hacer una transferencia): verbo en raíz + dezaket (yo), dezakezu (tú), dezake (él/ella). Dirua atera dezaket? (¿puedo sacar dinero?).": "Pour « pouvoir » avec un objet (retirer de l'argent, faire un virement) : radical du verbe + dezaket (je), dezakezu (tu), dezake (il/elle). Dirua atera dezaket ? (je peux retirer de l'argent ?).",
  "La raíz del verbo": "Le radical du verbe",
  "En la forma cuidada, con -ke el verbo va en raíz: bidali → bidal dezaket, ikusi → ikus dezaket, konpondu → konpon dezakezu. En la calle se oye mucho también con el verbo entero (konpondu dezakezu, utzi dezaket); las dos se entienden y aquí verás ambas.": "En langue soignée, avec -ke le verbe prend son radical : bidali → bidal dezaket, ikusi → ikus dezaket, konpondu → konpon dezakezu. À l'oral, on entend aussi beaucoup le verbe entier (konpondu dezakezu, utzi dezaket) ; les deux se comprennent et tu verras les deux ici.",
  "El negativo sigue siendo el de siempre: ezin dut (no puedo), ezin dut gaur etorri. Y «puedo» también se dice ahal dut: etorri ahal naiz. dezaket es un poco más formal.": "Le négatif reste celui de toujours : ezin dut (je ne peux pas), ezin dut gaur etorri. Et « je peux » se dit aussi ahal dut : etorri ahal naiz. dezaket est un peu plus formel.",
  "Buenos días. Quiero abrir una cuenta.": "Bonjour. Je veux ouvrir un compte.",
  "Bien. ¿Ha traído el DNI? Tiene que rellenar este formulario.": "Bien. Vous avez apporté votre carte d'identité ? Vous devez remplir ce formulaire.",
  "¿Puedo firmar aquí?": "Je peux signer ici ?",
  "Sí. Recibirá la tarjeta en casa dentro de una semana.": "Oui. Vous recevrez la carte chez vous dans une semaine.",
  "Pedir cita": "Prendre rendez-vous",
  "Noiz etor naiteke? · hitzordua aldatu · dokumentuak": "Noiz etor naiteke? · hitzordua aldatu · dokumentuak",
