  "lleno, completo": "complet",
  "por la mañana · por la tarde": "le matin · l'après-midi",
  "cuanto antes": "au plus vite",
  "la lista de espera": "la liste d'attente",
  "¿Para cuándo?": "Pour quand ?",
  "Quiero pedir cita con el médico.": "Je veux prendre rendez-vous avec le médecin.",
  "¿Cuándo puedo venir?": "Quand est-ce que je peux venir ?",
  "¿Puedes venir el lunes a las diez?": "Tu peux venir lundi à dix heures ?",
  "No puedo venir a esa hora; ¿puedo venir por la tarde?": "Je ne peux pas venir à cette heure-là ; je peux venir l'après-midi ?",
  "Por la tarde está lleno. El miércoles hay libre.": "L'après-midi, c'est complet. Mercredi il y a de la place.",
  "¿Puedo cambiar la cita?": "Je peux changer le rendez-vous ?",
  "Necesito cita para empadronarme.": "J'ai besoin d'un rendez-vous pour me faire recenser.",
  "¿Qué documentos tengo que traer?": "Quels documents dois-je apporter ?",
  "El DNI y el contrato de la casa.": "La carte d'identité et le contrat du logement.",
  "Puedes recoger el certificado allí mismo.": "Tu peux récupérer le certificat sur place.",
  "Lo necesito cuanto antes.": "J'en ai besoin au plus vite.",
  "Le pondré en la lista de espera.": "Je vous mets sur la liste d'attente.",
  "Puedo venir: etor naiteke": "Je peux venir : etor naiteke",
  "Con verbos sin objeto (venir, ir, quedarse) el potencial es naiteke (yo), zaitezke (tú), daiteke (él/ella), gaitezke (nosotros): etor naiteke? (¿puedo venir?), joan zaitezke (puedes ir).": "Avec les verbes sans objet (venir, aller, rester), le potentiel est naiteke (je), zaitezke (tu), daiteke (il/elle), gaitezke (nous) : etor naiteke ? (je peux venir ?), joan zaitezke (tu peux y aller).",
  "Raíz otra vez": "Le radical, encore",
  "etorri → etor naiteke, joan → joan naiteke, geratu → gera naiteke, sartu → sar naiteke. Igual que con dezaket: se quita -i / -tu.": "etorri → etor naiteke, joan → joan naiteke, geratu → gera naiteke, sartu → sar naiteke. Comme avec dezaket : on enlève -i / -tu.",
  "Para cuándo: noizko": "Pour quand : noizko",
  "noizko? (¿para cuándo?), biharko (para mañana), astelehenerako (para el lunes), datorren asterako (para la semana que viene). Es -ko / -rako con tiempo.": "noizko ? (pour quand ?), biharko (pour demain), astelehenerako (pour lundi), datorren asterako (pour la semaine prochaine). C'est -ko / -rako avec le temps.",
  "Buenos días. Quiero pedir cita con el médico.": "Bonjour. Je veux prendre rendez-vous avec le médecin.",
  "¿Puede venir el lunes a las diez?": "Vous pouvez venir lundi à dix heures ?",
  "No puedo a esa hora. ¿Puedo venir por la tarde?": "Je ne peux pas à cette heure-là. Je peux venir l'après-midi ?",
  "Por la tarde está lleno. ¿El miércoles a las cinco?": "L'après-midi, c'est complet. Mercredi à cinq heures ?",
  "Vale. ¿Qué tengo que traer?": "D'accord. Qu'est-ce que je dois apporter ?",
  "Solo la tarjeta sanitaria.": "Seulement la carte de santé.",
  "Por teléfono": "Au téléphone",
  "Bai, esan? · Mirenekin hitz egin dezaket? · mezu bat utzi": "Bai, esan? · Mirenekin hitz egin dezaket? · mezu bat utzi",
  "Dei bat bulegora · una llamada a la oficina": "Dei bat bulegora · un appel au bureau",
  "___-ekin hitz egin dezaket? · mezu bat utzi dezaket?": "___-ekin hitz egin dezaket? · mezu bat utzi dezaket?",
  "¿Sí, dígame?": "Allô, oui ?",
  "Soy Jon.": "C'est Jon.",
  "¿Puedo hablar con Miren?": "Je peux parler à Miren ?",
  "Un momento, por favor.": "Un instant, s'il vous plaît.",
  "No está.": "Il/elle n'est pas là.",
  "¿Puedo dejar un mensaje?": "Je peux laisser un message ?",
  "Llamaré luego.": "Je rappellerai plus tard.",
  "Se ha equivocado.": "Vous vous êtes trompé de numéro.",
  "No te oigo.": "Je ne t'entends pas.",
  "Tengo mala cobertura.": "Je capte mal.",
  "Se ha cortado la llamada.": "L'appel a été coupé.",
  "el número": "le numéro",
  "la extensión": "le poste",
  "la oficina": "le bureau",
  "está en una reunión": "il/elle est en réunion",
  "para Miren": "pour Miren",
  "para ti": "pour toi",
  "Adiós, gracias.": "Au revoir, merci.",
  "Buenos días, soy Jon. ¿Puedo hablar con Miren?": "Bonjour, c'est Jon. Je peux parler à Miren ?",
  "Ahora no está; está en una reunión.": "Elle n'est pas là ; elle est en réunion.",
  "Dígale, por favor, que ha llamado Jon.": "Dites-lui, s'il vous plaît, que Jon a appelé.",
  "Tiene mi número. Llamaré luego otra vez.": "Elle a mon numéro. Je rappellerai plus tard.",
  "Perdone, se ha equivocado.": "Excusez-moi, vous vous êtes trompé de numéro.",
  "No te oigo bien, tengo mala cobertura.": "Je t'entends mal, je capte mal.",
  "Se ha cortado la llamada. ¿Puedes llamar otra vez?": "L'appel a été coupé. Tu peux rappeler ?",
  "Este mensaje es para Miren.": "Ce message est pour Miren.",
  "Vale, se lo diré. ¡Adiós!": "D'accord, je le lui dirai. Au revoir !",
  "Al teléfono": "Au téléphone",
  "Bai, esan? / Bai? (al descolgar), nor da? (¿quién es?), X naiz (soy X), X-ekin hitz egin dezaket? (¿puedo hablar con X?), une batez (un momento), ez dago (no está), mezu bat utzi dezaket?": "Bai, esan ? / Bai ? (en décrochant), nor da ? (qui est-ce ?), X naiz (c'est X), X-ekin hitz egin dezaket ? (je peux parler à X ?), une batez (un instant), ez dago (il/elle n'est pas là), mezu bat utzi dezaket ?",
  "Para quién: -rentzat": "Pour qui : -rentzat",
  "Mirenentzat (para Miren), zuretzat (para ti), niretzat (para mí), amarentzat (para mamá), lagunentzat (para los amigos). Es -ren + -tzat.": "Mirenentzat (pour Miren), zuretzat (pour toi), niretzat (pour moi), amarentzat (pour maman), lagunentzat (pour les amis). C'est -ren + -tzat.",
  "Problemas de línea": "Problèmes de ligne",
  "ez dizut entzuten (no te oigo), estaldura txarra daukat (tengo mala cobertura), deia moztu da (se ha cortado), oker deitu duzu (se ha equivocado).": "ez dizut entzuten (je ne t'entends pas), estaldura txarra daukat (je capte mal), deia moztu da (ça a coupé), oker deitu duzu (vous vous êtes trompé de numéro).",
  "Un momento… Ahora no está, está en una reunión.": "Un instant… Elle n'est pas là, elle est en réunion.",
  "¿Puedo dejar un mensaje? Dígale, por favor, que ha llamado Jon.": "Je peux laisser un message ? Dites-lui, s'il vous plaît, que Jon a appelé.",
  "Vale, se lo diré. ¿Tiene su número?": "D'accord, je le lui dirai. Elle a votre numéro ?",
  "Sí, lo tiene. ¡Gracias, adiós!": "Oui, elle l'a. Merci, au revoir !",
