  "para la semana": "pour la semaine",
  "¿Cuándo puede venir?": "Quand pouvez-vous venir ?",
  "Hola, tengo un problema en casa.": "Bonjour, j'ai un problème à la maison.",
  "La calefacción no funciona.": "Le chauffage ne marche pas.",
  "El grifo de la cocina está roto y hay una fuga de agua.": "Le robinet de la cuisine est cassé et il y a une fuite d'eau.",
  "¿Puede venir hoy?": "Vous pouvez venir aujourd'hui ?",
  "Hoy no puedo; puedo venir mañana por la mañana.": "Aujourd'hui je ne peux pas ; je peux venir demain matin.",
  "¡Es urgente!": "C'est urgent !",
  "¿Puede arreglarlo hoy mismo?": "Vous pouvez le réparer aujourd'hui même ?",
  "¿Para cuándo estará arreglado?": "Pour quand ce sera réparé ?",
  "Para mañana, seguro.": "Pour demain, c'est sûr.",
  "¿Cuánto costará? ¿Puede darme un presupuesto?": "Combien ça coûtera ? Vous pouvez me faire un devis ?",
  "Se ha ido la luz en toda la casa.": "Il n'y a plus de courant dans toute la maison.",
  "¡He dejado la llave dentro y la puerta se ha quedado cerrada!": "J'ai laissé la clé à l'intérieur et la porte s'est refermée !",
  "No funciona: ez dabil": "Ça ne marche pas : ez dabil",
  "dabil (de ibili, «andar») se usa para máquinas: berogailua ez dabil (no funciona), garbigailua ondo dabil. Roto: apurtuta / hautsita dago.": "dabil (de ibili, « marcher ») s'emploie pour les machines : berogailua ez dabil (ça ne marche pas), garbigailua ondo dabil. Cassé : apurtuta / hautsita dago.",
  "Puede usted: dezakezu, zaitezke": "Vous pouvez : dezakezu, zaitezke",
  "Con objeto: konpondu dezakezu? (¿puede arreglarlo?), aurrekontu bat eman dezakezu? Sin objeto: etor zaitezke? (¿puede venir?).": "Avec objet : konpondu dezakezu ? (vous pouvez le réparer ?), aurrekontu bat eman dezakezu ? Sans objet : etor zaitezke ? (vous pouvez venir ?).",
  "Para mañana: biharko": "Pour demain : biharko",
  "noizko? → biharko (para mañana), gaurko (para hoy), asterako (para la semana), ostiralerako (para el viernes). -ko tras vocal, -erako tras consonante.": "noizko ? → biharko (pour demain), gaurko (pour aujourd'hui), asterako (pour la semaine), ostiralerako (pour vendredi). -ko après voyelle, -erako après consonne.",
  "Hola, ¿el fontanero? Tengo un problema: el grifo de la cocina está roto y hay una fuga.": "Bonjour, le plombier ? J'ai un problème : le robinet de la cuisine est cassé et il y a une fuite.",
  "¿Una fuga? Eso es urgente. Cierre la llave general.": "Une fuite ? C'est urgent. Fermez le robinet général.",
  "Hecho. ¿Puede venir hoy?": "C'est fait. Vous pouvez venir aujourd'hui ?",
  "Puedo venir hoy por la tarde, a las seis. ¿Bien?": "Je peux venir cet après-midi, à six heures. Ça va ?",
  "Perfecto. ¿Cuánto costará?": "Parfait. Combien ça coûtera ?",
  "Se lo diré después de verlo.": "Je vous le dirai après avoir vu.",
  "En la estación": "À la gare",
  "Txartel bat Donostiarako · zein nasatik? · atzerapena": "Txartel bat Donostiarako · zein nasatik? · atzerapena",
  "Iruñeko autobus-geltokian · en la estación de autobuses de Pamplona": "Iruñeko autobus-geltokian · à la gare routière de Pampelune",
  "Txartel bat ___-rako · zein ordutan irteten da?": "Txartel bat ___-rako · zein ordutan irteten da?",
