  "Al teléfono: fórmulas": "Au téléphone : les formules",
  "Las frases hechas del teléfono: Bai, esan? / Bai? (al descolgar), Nor da? (¿quién es?), X naiz (soy X), X-ekin hitz egin dezaket? (¿puedo hablar con X?), une batez, mesedez (un momento), ez dago (no está), mezu bat utzi dezaket? (¿puedo dejar un mensaje?), gero deituko dut (llamaré luego), oker deitu duzu (se ha equivocado), ez dizut entzuten (no te oigo), deia moztu da (se ha cortado). Para despedirse: agur, eskerrik asko.": "Les formules du téléphone : Bai, esan ? / Bai ? (en décrochant), Nor da ? (qui est-ce ?), X naiz (c'est X), X-ekin hitz egin dezaket ? (je peux parler à X ?), une batez, mesedez (un instant), ez dago (il/elle n'est pas là), mezu bat utzi dezaket ? (je peux laisser un message ?), gero deituko dut (je rappellerai), oker deitu duzu (vous vous êtes trompé), ez dizut entzuten (je ne t'entends pas), deia moztu da (ça a coupé). Pour prendre congé : agur, eskerrik asko.",
