  "Se me rompió: nor-nori en pasado": "Il s'est cassé : nor-nori au passé",
  "Las cosas que te pasan sin querer (romperse, olvidarse, perderse, caerse) van con dativo, como gustatu: apurtu zait (se me ha roto), ahaztu zait (se me ha olvidado), galdu zait (se me ha perdido), erori zait (se me ha caído). En pasado: zitzaidan (a mí), zitzaizun (a ti), zitzaion (a él/ella), zitzaigun (a nosotros). Con varias cosas, -zki-: galdu zitzaizkidan (se me perdieron las llaves). Y gertatu (pasar): zer gertatu zitzaizun? (¿qué te pasó?).": "Les choses qui t'arrivent sans le vouloir (se casser, oublier, perdre, tomber) prennent le datif, comme gustatu : apurtu zait (il s'est cassé), ahaztu zait (j'ai oublié), galdu zait (je l'ai perdu), erori zait (il est tombé). Au passé : zitzaidan (à moi), zitzaizun (à toi), zitzaion (à lui/elle), zitzaigun (à nous). Avec plusieurs choses, -zki- : galdu zitzaizkidan (j'ai perdu mes clés). Et gertatu (arriver) : zer gertatu zitzaizun ? (qu'est-ce qui t'est arrivé ?).",
